#include <bits/stdc++.h>
using namespace std;
using ll = long long;


ll comp(vector<ll>&pre, int x,int y,int m){
    int p1= x;
    int p2= x + 2*y;
    int p3 = m - 2*x - y;
    
    return 2*pre[p1] + pre[p2] + 3*pre[p3];
}
int main() {
	// your code goes here
    int t;
    cin >> t;
    
    while (t--) {
        int n;
        cin >> n;
        
        int m = 3*n;
        
        vector<ll> a(m);
        for(int i=0;i<m;i++) cin >> a[i];
        
        sort(a.rbegin(),a.rend());
        vector<ll> pre(m+1, 0);
        
        
        for(int i=0;i<m;i++){
            pre[i+1] = pre[i] + a[i];
        }
        
        ll ans = 0;
        
        for(int i=0;i<=n;i++){
            int maxy = n-i;
            
            // auto comp = [&] int (y)=>{
            //     int p1= i;
            //     int p2 = i+2*y;
            //     int p3 = 3*n 
            // }
            
            int low = 0, high = maxy-1;
            int best = 0;
            
            while(low<=high){
                int mid = low + (high- low)/2;
                int i1 = i + 2*mid;
                int i2 = m - 2*i - mid - 1;
                int diff = a[i1] + a[i1+1] - 3*a[i2];
                
                if(diff >=0){
                    best = mid +1 ;
                    low = mid+1;
                }
                else{
                    high = mid-1;
                }
            }
            
            ans = max(ans, comp(pre,i,best,m));
            if(best>0){
                ans = max(ans, comp(pre,i,best-1,m));
            }
            if(best < maxy){
                ans = max(ans, comp(pre,i, best+1,m));
            }
        }
        cout<<ans<<endl;
        
        
    }
}
